// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/healthz", wrapper.GetHealth)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/readyz", wrapper.GetReadiness)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/v1/auth/email", wrapper.SetAuthEmail)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/v1/auth/session", wrapper.DeleteAuthSession)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/auth/session", wrapper.GetAuthSession)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/auth/sessions", wrapper.CreateAuthSession)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/auth/users", wrapper.CreateAuthUser)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/authors/{author_id}", wrapper.GetAuthor)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/authors/{author_id}/notes", wrapper.ListAuthorNotes)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/categories", wrapper.ListCategories)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/comments/{comment_id}/replies", wrapper.CreateCommentReply)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/events", wrapper.CreateEvents)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/media/image-uploads", wrapper.PrepareImageUpload)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/media/images/{image_id}", wrapper.GetMediaImage)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/notes", wrapper.ListNotes)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/notes", wrapper.CreateNote)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/v1/notes/{note_id}", wrapper.DeleteNote)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/notes/{note_id}", wrapper.GetNote)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/v1/notes/{note_id}", wrapper.UpdateNote)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/notes/{note_id}/comments", wrapper.ListNoteComments)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/notes/{note_id}/comments", wrapper.CreateNoteComment)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/v1/notes/{note_id}/comments/{comment_id}", wrapper.DeleteNoteComment)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/v1/notes/{note_id}/useful", wrapper.UnmarkNoteUseful)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/v1/notes/{note_id}/useful", wrapper.MarkNoteUseful)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/v1/reports", wrapper.CreateReport)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/v1/search/notes", wrapper.SearchNotes)
	})

	return r
}

