// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Check process health
	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// Check API readiness
	// (GET /readyz)
	GetReadiness(ctx context.Context, request GetReadinessRequestObject) (GetReadinessResponseObject, error)
	// Set or change the current user's contact email
	// (PUT /v1/auth/email)
	SetAuthEmail(ctx context.Context, request SetAuthEmailRequestObject) (SetAuthEmailResponseObject, error)
	// Delete the current authenticated session
	// (DELETE /v1/auth/session)
	DeleteAuthSession(ctx context.Context, request DeleteAuthSessionRequestObject) (DeleteAuthSessionResponseObject, error)
	// Get the current authenticated session
	// (GET /v1/auth/session)
	GetAuthSession(ctx context.Context, request GetAuthSessionRequestObject) (GetAuthSessionResponseObject, error)
	// Create an authenticated session
	// (POST /v1/auth/sessions)
	CreateAuthSession(ctx context.Context, request CreateAuthSessionRequestObject) (CreateAuthSessionResponseObject, error)
	// Create a user account
	// (POST /v1/auth/users)
	CreateAuthUser(ctx context.Context, request CreateAuthUserRequestObject) (CreateAuthUserResponseObject, error)
	// Get a public author profile
	// (GET /v1/authors/{author_id})
	GetAuthor(ctx context.Context, request GetAuthorRequestObject) (GetAuthorResponseObject, error)
	// List an author's notes
	// (GET /v1/authors/{author_id}/notes)
	ListAuthorNotes(ctx context.Context, request ListAuthorNotesRequestObject) (ListAuthorNotesResponseObject, error)
	// List category catalog
	// (GET /v1/categories)
	ListCategories(ctx context.Context, request ListCategoriesRequestObject) (ListCategoriesResponseObject, error)
	// Reply to a top-level note comment
	// (POST /v1/comments/{comment_id}/replies)
	CreateCommentReply(ctx context.Context, request CreateCommentReplyRequestObject) (CreateCommentReplyResponseObject, error)
	// Record product events
	// (POST /v1/events)
	CreateEvents(ctx context.Context, request CreateEventsRequestObject) (CreateEventsResponseObject, error)
	// Stage one private image upload
	// (POST /v1/media/image-uploads)
	PrepareImageUpload(ctx context.Context, request PrepareImageUploadRequestObject) (PrepareImageUploadResponseObject, error)
	// Serve an attached image
	// (GET /v1/media/images/{image_id})
	GetMediaImage(ctx context.Context, request GetMediaImageRequestObject) (GetMediaImageResponseObject, error)
	// List recent notes
	// (GET /v1/notes)
	ListNotes(ctx context.Context, request ListNotesRequestObject) (ListNotesResponseObject, error)
	// Create a note
	// (POST /v1/notes)
	CreateNote(ctx context.Context, request CreateNoteRequestObject) (CreateNoteResponseObject, error)
	// Delete a note
	// (DELETE /v1/notes/{note_id})
	DeleteNote(ctx context.Context, request DeleteNoteRequestObject) (DeleteNoteResponseObject, error)
	// Get a note
	// (GET /v1/notes/{note_id})
	GetNote(ctx context.Context, request GetNoteRequestObject) (GetNoteResponseObject, error)
	// Update a note
	// (PATCH /v1/notes/{note_id})
	UpdateNote(ctx context.Context, request UpdateNoteRequestObject) (UpdateNoteResponseObject, error)
	// List note comments
	// (GET /v1/notes/{note_id}/comments)
	ListNoteComments(ctx context.Context, request ListNoteCommentsRequestObject) (ListNoteCommentsResponseObject, error)
	// Create a note comment
	// (POST /v1/notes/{note_id}/comments)
	CreateNoteComment(ctx context.Context, request CreateNoteCommentRequestObject) (CreateNoteCommentResponseObject, error)
	// Delete a note comment
	// (DELETE /v1/notes/{note_id}/comments/{comment_id})
	DeleteNoteComment(ctx context.Context, request DeleteNoteCommentRequestObject) (DeleteNoteCommentResponseObject, error)
	// Remove a useful mark from a note
	// (DELETE /v1/notes/{note_id}/useful)
	UnmarkNoteUseful(ctx context.Context, request UnmarkNoteUsefulRequestObject) (UnmarkNoteUsefulResponseObject, error)
	// Mark a note as useful
	// (PUT /v1/notes/{note_id}/useful)
	MarkNoteUseful(ctx context.Context, request MarkNoteUsefulRequestObject) (MarkNoteUsefulResponseObject, error)
	// Create a report
	// (POST /v1/reports)
	CreateReport(ctx context.Context, request CreateReportRequestObject) (CreateReportResponseObject, error)
	// Search notes
	// (GET /v1/search/notes)
	SearchNotes(ctx context.Context, request SearchNotesRequestObject) (SearchNotesResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// GetHealth operation middleware
func (sh *strictHandler) GetHealth(w http.ResponseWriter, r *http.Request) {
	var request GetHealthRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.GetHealth(ctx, request.(GetHealthRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "GetHealth")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(GetHealthResponseObject); ok {
		if err := validResponse.VisitGetHealthResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

